package de.ostms.lc.lc.api;import de.ostms.lc.audit.service.AuditService;import de.ostms.lc.check.service.DocumentCheckService;import de.ostms.lc.lc.domain.Amendment;import de.ostms.lc.lc.service.AmendmentService;import org.springframework.http.MediaType;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class AmendmentController{private final AmendmentService service;private final DocumentCheckService checks;private final AuditService audit;public AmendmentController(AmendmentService s,DocumentCheckService c,AuditService a){service=s;checks=c;audit=a;}@PostMapping(value="/lcs/import/mt707",consumes=MediaType.TEXT_PLAIN_VALUE)public Amendment importMt707(@RequestBody String raw,Authentication auth){Amendment amendment=service.importMt707(raw);UUID id=amendment.getLetterOfCredit().getId();audit.record(auth,"MT707_RECEIVED","LETTER_OF_CREDIT",id,"Amendment "+amendment.getAmendmentNumber()+" (offen)");return amendment;}
@PostMapping("/lcs/{lcId}/amendments/{id}/accept")public Amendment accept(@PathVariable UUID lcId,@PathVariable UUID id,@RequestBody(required=false) java.util.Map<String,String> body,Authentication auth){Amendment amendment=service.accept(owned(lcId,id),auth.getName(),body==null?null:body.get("comment"));long reset=checks.invalidateDecisions(lcId);audit.record(auth,"AMENDMENT_ACCEPTED","LETTER_OF_CREDIT",lcId,"Amendment "+amendment.getAmendmentNumber());if(reset>0)audit.record(auth,"DOCUMENT_CHECK_DECISIONS_RESET","LETTER_OF_CREDIT",lcId,reset+" Entscheidungen wegen angenommener Änderung zurückgesetzt");return amendment;}
@PostMapping("/lcs/{lcId}/amendments/{id}/reject")public Amendment reject(@PathVariable UUID lcId,@PathVariable UUID id,@RequestBody(required=false) java.util.Map<String,String> body,Authentication auth){Amendment amendment=service.reject(owned(lcId,id),auth.getName(),body==null?null:body.get("comment"));audit.record(auth,"AMENDMENT_REJECTED","LETTER_OF_CREDIT",lcId,"Amendment "+amendment.getAmendmentNumber());return amendment;}
private UUID owned(UUID lcId,UUID id){if(service.forLc(lcId).stream().noneMatch(a->a.getId().equals(id)))throw new java.util.NoSuchElementException("Änderung nicht gefunden.");return id;}
@GetMapping("/lcs/{id}/amendments")public List<Amendment> amendments(@PathVariable UUID id){return service.forLc(id);}}
